insert into public.organizations (code, name_ko, description, core_values, talent_profile, category, pass_threshold, veto_threshold, eliminate_threshold)
values
  ('KAMCO', '한국자산관리공사', '한국자산관리공사는 가계·기업·공공자산의 사회·경제적 가치를 높이는 국내 유일의 공적자산관리전문기관입니다.', '["책임", "상생", "혁신", "신뢰"]'::jsonb, '{"talents": ["전문성을 갖춘 인재", "미래에 도전하는 인재", "포용하고 존중하는 인재"], "mission": "금융회사 건전성 제고, 경제주체 재기 도모, 공공자산 가치 제고를 통해 금융산업 및 국가경제 발전에 이바지합니다.", "business": ["부실채권 인수·정리", "기업구조조정 지원", "가계 신용회복 지원", "국유재산 관리·개발", "체납조세정리", "온비드 시스템 운영"], "issues": ["해외이주 채무자 채권 미회수 문제", "부실정리 넘어 재기 지원 역할 확대", "새출발기금 등으로 인한 부채 증가", "AI 기반 업무 혁신 추진"], "interview": "신입 면접은 NCS 기반으로 직무 관련 PT, 경력/경험 기반 심층 인터뷰, 업무/민원 상황면접 등 구조화된 면접을 통해 직무역량 및 조직 적합성을 심층 검증하며, 인성검사도 포함됩니다. PT 면접의 비중이 높고 캠코 관련 심층적인 이해가 요구됩니다."}'::jsonb, '금융', 70, 50, 30),
  ('BOK', '한국은행', '한국은행은 물가안정, 금융안정, 지급결제제도 운영 등을 통해 국민경제 발전에 이바지합니다.', '["신뢰성", "전문성", "독립성"]'::jsonb, '{"mission": "국가경제의 안정과 발전을 이끄는 한국은행", "business": ["통화신용정책 수립·집행", "금융안정 도모", "지급결제제도 운영·감시", "화폐 발행 및 관리", "외환보유액 운용"], "issues": ["물가·금융안정 및 정책 조화", "외환시장 안정 및 원화 국제화", "디지털 금융 인프라 구축 (자산 토큰화, CBDC 등)"], "interview": "한국은행 신입 면접은 필기시험 후 PT 및 토론, 인성면접, 총재/임원면접 등 다단계로 진행됩니다. 기관의 자질과 특성에 대한 이해를 바탕으로 본인의 역량을 자연스럽게 보여주는 것이 중요합니다."}'::jsonb, '금융', 70, 50, 30),
  ('HF', '한국주택금융공사', '국민의 주거안정을 위해 주택금융을 장기적·안정적으로 공급하는 정책금융기관입니다.', '["국민 중심", "미래 지향", "책임과 신뢰"]'::jsonb, '{"talents": ["창조인", "전문인", "화합인"], "mission": "주택금융의 장기적·안정적 공급을 통해 국민 복지증진과 국민경제 발전에 기여합니다.", "business": ["보금자리론", "주택연금", "주택보증", "유동화증권 발행", "정책모기지 공급"], "issues": ["주택시장 안정화 및 주거안정 지원", "녹색 주택금융 확대 및 ESG 경영 강화", "디지털 전환 가속화 및 AI 기반 서비스 혁신"], "interview": "신입 면접은 주로 자기소개서 기반의 경험 검증 중심 인성 면접으로 진행됩니다. 공사 사업 및 상품 지식 질문 비중이 있을 수 있어 폭넓은 준비가 중요하며, 민원 및 갈등 해결 능력에 대한 질문이 나올 수 있습니다."}'::jsonb, '금융', 65, 45, 30),
  ('HUG', '주택도시보증공사', 'HUG는 주택 관련 보증업무 및 정책사업 수행과 주택도시기금 운용·관리를 통해 국민 주거복지 증진과 도시재생 활성화를 지원하는 공기업이다.', '["국민만족", "책임", "소통", "혁신"]'::jsonb, '{"talents": ["변화를 선도하는 주도적 인재", "최고 전문가를 지향하는 인재", "고객과 국민에게 신뢰받는 인재"], "mission": "국민의 주거안정과 주택공급 활성화를 위한 금융지원 및 정책사업 수행으로 국민 삶의 질 향상에 이바지한다.", "business": ["주택분양보증", "전세보증금반환보증", "임대보증금보증", "주택사업금융(PF)보증", "주택도시기금 운용"], "issues": ["전세사기 대응 및 보증제도 개선", "중도금대출 보증사고 증가 리스크 관리", "주택시장 변동성 대응 및 공급 활성화"], "interview": "신입 면접은 1차(NCS 기반 역량 면접: 직무, PT, 인성)와 2차(임원 면접)로 진행되며, 토론면접, PT면접, 심층(인성·경험 기반) 면접이 포함된다. 직무/사업 이해도와 솔직한 태도가 중요하며, PT 면접이 까다로운 편이다."}'::jsonb, '금융', 65, 45, 30),
  ('KDB', '한국산업은행', '대한민국 산업 개발과 국민경제 발전을 위한 정책금융기관으로, 기업을 키우고 산업을 살리는 역할을 수행합니다.', '["고객 최우선", "변화 수용", "계산된 도전", "소통과 주도", "협력", "현장 중시", "미래 지향"]'::jsonb, '{"talents": ["고객 최우선", "변화 수용", "계산된 도전", "소통과 주도", "협력", "현장 중시", "미래 지향"], "mission": "대한민국 경제의 1%를 책임지는 정책금융기관으로서 금융산업과 국민경제 발전에 기여합니다.", "business": ["첨단전략산업 육성", "중소·중견기업 성장 지원", "그린·디지털 전환 촉진", "금융시장 안정화", "글로벌 시장 개척 지원"], "issues": ["첨단전략산업 육성 및 정책금융 확대", "녹색전환 선도 및 지역균형 발전", "글로벌 뱅킹시스템 재구축 및 디지털 전환"], "interview": "신입 면접은 직무면접, PT, 심층과제로 구성되며, 자기소개서 기반 질문과 시사 이슈에 대한 견해를 묻는 경우가 많습니다. 지원자의 역량과 KDB Way에 부합하는 인재상, 그리고 산업은행에 대한 이해도를 평가합니다."}'::jsonb, '금융', 70, 50, 30),
  ('IBK', '중소기업은행', '중소기업의 성장과 발전을 지원하며 국가 경제 활성화에 기여하는 정책금융기관입니다.', '["고객과 함께", "신뢰와 책임", "열정과 혁신", "소통과 팀웍"]'::jsonb, '{"talents": ["올바른 품성", "도전적", "창의적", "금융전문가", "고객우선", "자율과 책임", "소통과 팀웍"], "mission": "세상을 바꾸는 금융, 고객의 행복과 더 나은 세상을 만들어갑니다.", "business": ["기업금융", "개인금융", "국제금융", "신탁/퇴직연금", "카드사업"], "issues": ["생산적 금융 대전환 (30-300 프로젝트)", "디지털 전환 가속화", "중소기업 지원 강화 및 ESG 경영"], "interview": "신입 면접은 직무 PT, 개인발표, 팀토론, 심층인터뷰, 조직적합도, 최종 다대다 면접 등 다양한 형태로 진행됩니다. IBK 정체성 인지, 고객 특성 분석, 경청·공감·팀워크를 바탕으로 한 본인의 경험과 역량 어필이 중요합니다."}'::jsonb, '금융', 65, 45, 30),
  ('KEXIM', '한국수출입은행', '수출입, 해외투자 등 대외 경제협력 금융을 제공하여 국민경제 발전을 촉진하는 정책금융기관입니다.', '[]'::jsonb, '{"mission": "대외경제협력 증진을 통한 국민경제의 건전한 발전입니다.", "business": ["수출입 금융 지원", "해외 투자 금융", "해외 자원 개발 금융", "대외경제협력기금(EDCF) 운용", "남북협력기금(IKCF) 운용"], "issues": ["글로벌 공급망 안정화 및 전략산업 육성", "K-컬처 수출산업화 지원", "기후리스크 관리 및 탄소중립 달성"], "interview": "신입 면접은 NCS 기반 직무역량평가, PT 면접, 인성 면접으로 구성되며, 다대일 방식으로 진행됩니다. 조직가치 적합도와 직무 관련 역량을 평가하는 데 중점을 둡니다."}'::jsonb, '금융', 70, 50, 30),
  ('KODIT', '신용보증기금', '담보력 부족 기업의 채무를 보증하고 신용정보를 관리하여 국민경제 발전에 기여합니다.', '["고객", "성장", "혁신", "협력"]'::jsonb, '{"talents": ["기본인품", "성장자질", "혁신·소통의지", "논리적 사고력", "문제해결능력", "책임감·열정"], "mission": "기업의 미래 성장동력 확충과 국민경제 균형발전에 기여합니다.", "business": ["신용보증", "신용보험", "경영지도", "보증연계투자", "산업기반신용보증"], "issues": ["AI·미래전략산업 금융 지원 확대", "구상채권 부실 관리 강화", "초기·영세기업 지원 강화"], "interview": "면접은 과제수행, 실무, 심층면접으로 진행되며, 협업·논리적 사고·직무수행역량·청렴성·조직적합성을 종합 평가합니다. 중소기업 지원과 위험 통제 균형감각, 소통 역량, 기업심사 및 금융리스크 관리 역량이 중요하게 평가됩니다."}'::jsonb, '금융', 65, 45, 30),
  ('KIBO', '기술보증기금', '기술 혁신형 기업에 기술 보증 및 평가를 지원하여 기술 경쟁력 제고와 경제 성장에 기여합니다.', '["공정", "혁신", "연대"]'::jsonb, '{"talents": ["융합형 인재 (이공계, 상경계, 법학 직무 역량)"], "mission": "혁신기업과 함께 대한민국의 미래를 여는 글로벌 기술금융 허브입니다.", "business": ["기술보증", "기술평가", "보증연계투자", "기술지도 및 경영지도", "지식재산공제"], "issues": ["R&D사업화 프로젝트보증 신설 (R&D 성과 사업화 지원)", "청년 창업 금융지원 확대 (청년 창업 활성화)", "글로벌 기술금융 허브 도약 추진 (KIBO 2050 AGENDA)"], "interview": "신입 면접은 1차에서 PT(직무적합성), 토론, 조직적합성 면접을 진행하며, 특히 PT 면접은 기보 사업 및 경제 이슈에 대한 이해가 중요합니다. 2차 면접은 종합적합성을 평가하며, 1차 면접 및 필기전형 점수가 합산됩니다."}'::jsonb, '금융', 65, 45, 30),
  ('KDIC', '예금보험공사', '금융회사 파산 시 예금자 보호 및 금융제도 안정 유지를 위한 기관입니다.', '["국민신뢰", "전문성", "공정", "혁신"]'::jsonb, '{"talents": ["책임감(Together)", "소통(Open-minded)", "전문성(Professional)"], "mission": "금융계약자 보호 및 금융제도의 안정성 유지", "business": ["예금보험기금 조달", "부실금융회사 정리", "예금보험금 지급", "지원자금 회수", "착오송금 반환지원"], "issues": ["금융시장 리스크 관리 및 대응 고도화", "예금보험기금체계 개편 및 지속가능성 제고", "디지털 전환 가속화 및 AI 업무체계 구축"], "interview": "신입 면접은 다대다 인성 면접이 주를 이루며, 조직 적응력과 의사소통 능력을 중요하게 평가합니다. 금융일반 직무는 발표 및 토론 면접을 통해 금융 지식의 구조화 및 논리 유지 능력을 평가하며, 최근 금융 현안에 대한 이해도 중요합니다."}'::jsonb, '금융', 65, 45, 30),
  ('KIC', '한국투자공사', '정부 및 한국은행으로부터 위탁받은 자산을 해외에 장기·분산 투자하여 국부를 증대하고 금융산업 발전에 기여하는 국부펀드입니다.', '["성과", "전문성", "혁신", "책임", "팀워크"]'::jsonb, '{"talents": ["Professionalism (전문성)", "Integrity (청렴성)", "Loyalty (애사심)", "Accountability (책임감)", "Respect (존중)"], "mission": "국부를 증대하고 국가 미래가치를 실현하는 글로벌 일류 투자기관입니다.", "business": ["주식 투자", "채권 투자", "사모펀드 투자", "부동산 투자", "인프라 투자"], "issues": ["국내 PEF 출자 확대", "통합 포트폴리오 운용체계(TPA) 도입", "운용자산(AUM) 확대 및 수익률 제고"], "interview": "신입 면접은 서류-필기-1차(실무진/팀장급)-2차(임원진) 면접으로 진행됩니다. 이력서 및 자기소개서 기반 질문과 직무, 기관 이해도, 가치관을 평가하며, 투자운용 직무는 AI 관련 최신 이슈 질문이 나올 수 있습니다."}'::jsonb, '금융', 70, 50, 30),
